function getAssetById(list, id, fallbackId) {
  return list.find((item) => item.id === id) || list.find((item) => item.id === fallbackId) || list[0];
}
function normalizeAvatarData(input) {
  const next = input && typeof input === 'object' ? { ...input } : {};
  return {
    bodyId: getAssetById(AVATAR_BODIES, next.bodyId, DEFAULT_AVATAR.bodyId).id,
    hairId: getAssetById(AVATAR_HAIRS, next.hairId || next.hairstyleId, DEFAULT_AVATAR.hairId).id,
    eyesId: getAssetById(AVATAR_EYES, next.eyesId, DEFAULT_AVATAR.eyesId).id,
    lipsId: getAssetById(AVATAR_LIPS, next.lipsId, DEFAULT_AVATAR.lipsId).id,
    beardId: getAssetById(AVATAR_BEARDS, next.beardId, DEFAULT_AVATAR.beardId).id,
    mustacheId: getAssetById(AVATAR_MUSTACHES, next.mustacheId, DEFAULT_AVATAR.mustacheId).id,
    shirtId: getAssetById(AVATAR_SHIRTS, next.shirtId, DEFAULT_AVATAR.shirtId).id,
    hatId: getAssetById(AVATAR_HATS, next.hatId, DEFAULT_AVATAR.hatId).id,
  };
}
function getAvatarBody(avatar) { return getAssetById(AVATAR_BODIES, avatar?.bodyId, DEFAULT_AVATAR.bodyId); }
function getAvatarHair(avatar) { return getAssetById(AVATAR_HAIRS, avatar?.hairId || avatar?.hairstyleId, DEFAULT_AVATAR.hairId); }
function getAvatarEyes(avatar) { return getAssetById(AVATAR_EYES, avatar?.eyesId, DEFAULT_AVATAR.eyesId); }
function getAvatarLips(avatar) { return getAssetById(AVATAR_LIPS, avatar?.lipsId, DEFAULT_AVATAR.lipsId); }
function getAvatarBeard(avatar) { return getAssetById(AVATAR_BEARDS, avatar?.beardId, DEFAULT_AVATAR.beardId); }
function getAvatarMustache(avatar) { return getAssetById(AVATAR_MUSTACHES, avatar?.mustacheId, DEFAULT_AVATAR.mustacheId); }
function getAvatarShirt(avatar) { return getAssetById(AVATAR_SHIRTS, avatar?.shirtId, DEFAULT_AVATAR.shirtId); }
function getAvatarHat(avatar) { return getAssetById(AVATAR_HATS, avatar?.hatId, DEFAULT_AVATAR.hatId); }
function AvatarOptionButton({ item, selected, onClick, thumbHeight = 72 }) {
  const previewSrc = item.thumbSrc || item.src;
  return (
    <button
      onClick={onClick}
      title={item.label}
      style={{
        background: '#fff', borderRadius: 6, padding: 6, cursor: 'pointer',
        border: selected ? '3px solid #5C7A4F' : '1.5px solid #B8A98A',
        color: '#4A3728', fontFamily: sans,
      }}
    >
      {previewSrc ? (
        <img src={previewSrc} alt={item.label} style={{ width: '100%', height: thumbHeight, objectFit: 'contain', objectPosition: 'center center', display: 'block' }} />
      ) : (
        <div style={{ height: thumbHeight, display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700, fontSize: 12, color: '#4A3728', background: '#F7F2E7', borderRadius: 4 }}>{item.label}</div>
      )}
      <div style={{ fontSize: 10, fontWeight: 700, marginTop: 4, color: '#4A3728', lineHeight: 1.2 }}>{item.label}</div>
    </button>
  );
}





