      setInventory((inv) => ({ ...inv, comfreyleaves: (inv.comfreyleaves || 0) + 3 }));
      setGroundPlants((prev) => prev.map((p) => (p.gx === gx && p.gy === gy ? { ...p, harvested: true } : p)));
