                          <span style={{ flex: 1, marginLeft: 8 }}>
                            <div style={{ fontSize: 12, fontWeight: 700, color: '#3D2B1F' }}>{pest.name} × {counts[pestId]}</div>
                            <div style={{ fontSize: 9, color: '#6b5844' }}>Best: {best.name}</div>
                          </span>
